import React from 'react';
import cl from "../styles/friends.module.css";
import { useTranslation } from '../hooks/useTranslation';

const Clans = ({ url }) => {
    const language = localStorage.getItem('language') || 'en';
    const { t } = useTranslation(language);

    const renderContent = () => {
        return (
            <div className={cl.comingSoonContainer}>
                <div className={cl.comingSoonTitle}>
                    {t('airdrop.comingSoon') || 'Coming Soon'}
                </div>
                <div className={cl.comingSoonDescription}>
                    {t('airdrop.comingSoonDescription') || 'This feature is under development and will be available soon!'}
                </div>
            </div>
        );
    };

    return (
        <div className={`${cl.airdrop__container} ${cl.mt_20} ${cl.mb_30}`}>
            {renderContent()}
        </div>
    );
};

export default Clans;